export function onRequest(context) {
    const requestUrl = new URL(context.request.url);
    const slug = String(context.params.slug || "").trim().replace(/^\/+|\/+$/g, "");

    // Physical .html product pages are already generated by the static build.
    // Never redirect them back through this pretty-URL function.
    if (requestUrl.pathname.endsWith(".html")) {
        return context.next();
    }

    if (!slug || slug.includes(".")) {
        return context.next();
    }

    const target = new URL(requestUrl);
    target.pathname = `/bn/products/${encodeURIComponent(slug)}.html`;

    return Response.redirect(target.toString(), 301);
}
